{"implementation": "def solve(case):
    nodes = case['nodes']
    required_symbols = set(case['required_symbols'])
    # Build maps
    node_map = {}
    children_map = {}
    for n in nodes:
        nid = n['id']
        node_map[nid] = n
        children_map.setdefault(n['parent'], []).append(nid)

    present = set(node_map.keys())
    # initial symbol counts
    symbol_counts = {}
    for n in nodes:
        sym = n['symbol']
        symbol_counts[sym] = symbol_counts.get(sym, 0) + 1

    # Sort removable nodes by depth descending, then id ascending
    removable_nodes = [n for n in nodes if n['removable']]
    removable_nodes.sort(key=lambda x: (-x['depth'], x['id']))

    removed_order = []

    def get_subtree_ids(root_id):
        """Return set of node ids in the subtree of root_id that are still present."""
        subtree = set()
        stack = [root_id]
        while stack:
            nid = stack.pop()
            if nid in present:
                subtree.add(nid)
                for child in children_map.get(nid, []):
                    if child in present:
                        stack.append(child)
        return subtree

    for node in removable_nodes:
        nid = node['id']
        if nid not in present:
            continue
        # Check root, required symbol, retained children
        if node['parent'] is None:
            continue
        if node['symbol'] in required_symbols:
            continue
        # Check if any child is still present
        has_retained_child = any(cid in present for cid in children_map.get(nid, []))
        if has_retained_child:
            continue
        # Compute subtree that would be removed
        subtree_ids = get_subtree_ids(nid)
        # Check required symbols after removal
        required_ok = True
        for sym in required_symbols:
            # count after removal = current count - count in subtree
            count_in_subtree = sum(1 for sid in subtree_ids if node_map[sid]['symbol'] == sym)
            if symbol_counts.get(sym, 0) - count_in_subtree <= 0:
                required_ok = False
                break
        if not required_ok:
            continue
        # Remove
        for sid in subtree_ids:
            sym = node_map[sid]['symbol']
            symbol_counts[sym] -= 1
            present.remove(sid)
        removed_order.append(nid)

    retained_ids = sorted(present)
    return {
        'removed_node_ids': removed_order,
        'retained_node_ids': retained_ids
    }"}
